-- OP-146 I7, m.5 (b), (c), (f), m.10 (a); IDP-7, IDP-24, CR-38, TN-31, TN-50, MD-7, MD-10, OP-73:
-- the realm authorization server's state: pending authorization requests (PAR and interactive),
-- authorization codes, grants with their refresh token chains, pairwise subjects and the
-- private_key_jwt replay cache
SET LOCAL ROLE access_migrator;

-- CR-38: a client secret is generated by the server and only its digest is stored; RP-initiated
-- and back-channel logout endpoints are exact strings (§10.4.6)
ALTER TABLE access.idp_clients
  ADD COLUMN secret_hash bytea CHECK (octet_length(secret_hash) = 32),
  ADD COLUMN post_logout_redirect_uris text[] NOT NULL DEFAULT '{}'
    CHECK (cardinality(post_logout_redirect_uris) <= 32),
  ADD COLUMN backchannel_logout_uri text
    CHECK (length(backchannel_logout_uri) <= 2048 AND backchannel_logout_uri ~ '^https://'),
  ADD CONSTRAINT idp_clients_secret CHECK ((auth_method = 'client_secret_basic') = (secret_hash IS NOT NULL));

-- OP-146 m.5 (f): ephemeral protocol state is hash-keyed, PII-free and partitioned by day
CREATE FUNCTION access.secure_oauth_partition(t regclass) RETURNS void
  LANGUAGE plpgsql
  SET search_path = pg_catalog
  AS $$
BEGIN
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
  EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
  EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
  EXECUTE format('CREATE POLICY rows ON %s AS PERMISSIVE USING (true)', t);
  EXECUTE format('CREATE POLICY tenant_scope ON %s AS RESTRICTIVE TO access_app '
                 'USING (tenant_id = (SELECT access.tenant_scope()) AND realm_id = (SELECT access.realm_scope())) '
                 'WITH CHECK (tenant_id = (SELECT access.tenant_scope()) AND realm_id = (SELECT access.realm_scope()))', t);
  EXECUTE format('CREATE TRIGGER append_only_truncate BEFORE TRUNCATE ON %s '
                 'FOR EACH STATEMENT EXECUTE FUNCTION access.reject_mutation()', t);
END
$$;

-- RFC 9126, §17.1.3: a pushed or interactive authorization request, used once
CREATE TABLE access.oauth_requests (
  tenant_id uuid NOT NULL,
  realm_id uuid NOT NULL,
  day integer NOT NULL CHECK (day >= 0),
  request_hash bytea NOT NULL CHECK (octet_length(request_hash) = 32),
  client_uuid uuid NOT NULL,
  pushed boolean NOT NULL,
  params bytea NOT NULL CHECK (octet_length(params) <= 8192),
  created_ms bigint NOT NULL CHECK (created_ms > 0),
  expires_ms bigint NOT NULL CHECK (expires_ms > created_ms),
  used_ms bigint,
  PRIMARY KEY (tenant_id, realm_id, day, request_hash)
) PARTITION BY RANGE (day);
CREATE TABLE access.oauth_requests_default PARTITION OF access.oauth_requests DEFAULT;

-- §11.4.5 #20, IDP-7: an authorization code, redeemed once by compare-and-set
CREATE TABLE access.oauth_codes (
  tenant_id uuid NOT NULL,
  realm_id uuid NOT NULL,
  day integer NOT NULL CHECK (day >= 0),
  code_hash bytea NOT NULL CHECK (octet_length(code_hash) = 32),
  client_uuid uuid NOT NULL,
  session_id uuid NOT NULL,
  details bytea NOT NULL CHECK (octet_length(details) <= 8192),
  created_ms bigint NOT NULL CHECK (created_ms > 0),
  expires_ms bigint NOT NULL CHECK (expires_ms > created_ms),
  redeemed_ms bigint,
  grant_id uuid,
  CHECK ((redeemed_ms IS NULL) = (grant_id IS NULL)),
  PRIMARY KEY (tenant_id, realm_id, day, code_hash)
) PARTITION BY RANGE (day);
CREATE TABLE access.oauth_codes_default PARTITION OF access.oauth_codes DEFAULT;

-- §10.4.5, RFC 7523: client assertion jti replay cache, keyed by digest
CREATE TABLE access.client_assertion_replay (
  tenant_id uuid NOT NULL,
  realm_id uuid NOT NULL,
  day integer NOT NULL CHECK (day >= 0),
  key_hash bytea NOT NULL CHECK (octet_length(key_hash) = 32),
  PRIMARY KEY (tenant_id, realm_id, day, key_hash)
) PARTITION BY RANGE (day);
CREATE TABLE access.client_assertion_replay_default PARTITION OF access.client_assertion_replay DEFAULT;

CREATE FUNCTION access.oauth_ephemeral_rules() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog
  AS $$
BEGIN
  IF TG_OP <> 'UPDATE' OR TG_TABLE_NAME LIKE 'client_assertion_replay%' THEN
    RAISE EXCEPTION '%: % is not allowed', TG_TABLE_NAME, TG_OP USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_TABLE_NAME LIKE 'oauth_requests%' THEN
    IF OLD.used_ms IS NOT NULL THEN
      RAISE EXCEPTION '%: a used request never changes', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF OLD.redeemed_ms IS NOT NULL THEN
    RAISE EXCEPTION '%: a redeemed code never changes', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$$;

SELECT access.secure_oauth_partition(t::regclass) FROM unnest(ARRAY[
  'access.oauth_requests', 'access.oauth_requests_default', 'access.oauth_codes',
  'access.oauth_codes_default', 'access.client_assertion_replay',
  'access.client_assertion_replay_default']) AS t;
CREATE TRIGGER oauth_ephemeral_rules BEFORE UPDATE OR DELETE ON access.oauth_requests
  FOR EACH ROW EXECUTE FUNCTION access.oauth_ephemeral_rules();
CREATE TRIGGER oauth_ephemeral_rules BEFORE UPDATE OR DELETE ON access.oauth_codes
  FOR EACH ROW EXECUTE FUNCTION access.oauth_ephemeral_rules();
CREATE TRIGGER oauth_ephemeral_rules BEFORE UPDATE OR DELETE ON access.client_assertion_replay
  FOR EACH ROW EXECUTE FUNCTION access.oauth_ephemeral_rules();

-- OP-146 m.5 (f): the archive role opens each day ahead
CREATE FUNCTION access.open_oauth_day(d integer) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = pg_catalog
  AS $$
DECLARE
  t text;
  name text;
BEGIN
  IF d < 0 THEN
    RAISE EXCEPTION 'negative day' USING ERRCODE = 'check_violation';
  END IF;
  FOREACH t IN ARRAY ARRAY['oauth_requests', 'oauth_codes', 'client_assertion_replay'] LOOP
    name := format('%s_d%s', t, d);
    IF to_regclass(format('access.%I', name)) IS NULL THEN
      EXECUTE format('CREATE TABLE access.%I PARTITION OF access.%I FOR VALUES FROM (%s) TO (%s)',
                     name, t, d, d + 1);
      PERFORM access.secure_oauth_partition(format('access.%I', name)::regclass);
    END IF;
  END LOOP;
END
$$;

-- OP-146 m.5 (c), §7.9.12.4, TN-31: a grant is an identity record: the code exchange of one
-- session for one client, with its refresh chain; it dies with the session and the subject's
-- session_epoch (TN-50, G57) and is revoked, never deleted (OP-73)
CREATE TABLE access.oauth_grants (
  tenant_id uuid NOT NULL,
  realm_id uuid NOT NULL,
  grant_id uuid NOT NULL DEFAULT uuidv7(),
  sid bytea NOT NULL CHECK (octet_length(sid) = 16),
  client_uuid uuid NOT NULL,
  subject_id uuid NOT NULL,
  session_id uuid NOT NULL,
  session_epoch bigint NOT NULL CHECK (session_epoch >= 0),
  dpop_jkt bytea CHECK (octet_length(dpop_jkt) = 32),
  details bytea NOT NULL CHECK (octet_length(details) <= 4096),
  created_ms bigint NOT NULL CHECK (created_ms > 0),
  expires_ms bigint NOT NULL CHECK (expires_ms > created_ms),
  revoked_ms bigint,
  revoke_reason text CHECK (revoke_reason IN ('revoked', 'reuse', 'code_reuse', 'logout', 'epoch')),
  CHECK ((revoked_ms IS NULL) = (revoke_reason IS NULL)),
  PRIMARY KEY (tenant_id, realm_id, grant_id),
  UNIQUE (tenant_id, realm_id, sid),
  FOREIGN KEY (tenant_id, realm_id, client_uuid)
    REFERENCES access.idp_clients (tenant_id, realm_id, client_uuid),
  FOREIGN KEY (tenant_id, realm_id, subject_id)
    REFERENCES access.identity_subjects (tenant_id, realm_id, subject_id),
  FOREIGN KEY (tenant_id, realm_id, session_id)
    REFERENCES access.login_sessions (tenant_id, realm_id, session_id)
);
CREATE INDEX oauth_grants_session ON access.oauth_grants (tenant_id, realm_id, session_id)
  WHERE revoked_ms IS NULL;

-- CR-38, TN-31: refresh tokens are stored as digests; each is rotated once
CREATE TABLE access.oauth_refresh_tokens (
  tenant_id uuid NOT NULL,
  realm_id uuid NOT NULL,
  token_hash bytea NOT NULL CHECK (octet_length(token_hash) = 32),
  grant_id uuid NOT NULL,
  created_ms bigint NOT NULL CHECK (created_ms > 0),
  rotated_ms bigint,
  PRIMARY KEY (tenant_id, realm_id, token_hash),
  FOREIGN KEY (tenant_id, realm_id, grant_id)
    REFERENCES access.oauth_grants (tenant_id, realm_id, grant_id)
);

-- MD-10, IDP-24, OP-146 m.5 (b): a pairwise subject is a random value per subject and sector,
-- never derived; the sector is the client
CREATE TABLE access.pairwise_subjects (
  tenant_id uuid NOT NULL,
  realm_id uuid NOT NULL,
  subject_id uuid NOT NULL,
  sector uuid NOT NULL,
  value text NOT NULL CHECK (value ~ '^[A-Za-z0-9_-]{43}$'),
  PRIMARY KEY (tenant_id, realm_id, subject_id, sector),
  UNIQUE (tenant_id, realm_id, value),
  FOREIGN KEY (tenant_id, realm_id, subject_id)
    REFERENCES access.identity_subjects (tenant_id, realm_id, subject_id)
);

CREATE FUNCTION access.oauth_grant_rules() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog
  AS $$
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RAISE EXCEPTION '%: % is not allowed', TG_TABLE_NAME, TG_OP USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_TABLE_NAME = 'oauth_grants' THEN
    IF OLD.revoked_ms IS NOT NULL THEN
      RAISE EXCEPTION 'oauth_grants: a revoked grant stays revoked' USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF OLD.rotated_ms IS NOT NULL THEN
    RAISE EXCEPTION 'oauth_refresh_tokens: a token is rotated once' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER oauth_grant_rules BEFORE UPDATE OR DELETE ON access.oauth_grants
  FOR EACH ROW EXECUTE FUNCTION access.oauth_grant_rules();
CREATE TRIGGER oauth_grant_rules BEFORE UPDATE OR DELETE ON access.oauth_refresh_tokens
  FOR EACH ROW EXECUTE FUNCTION access.oauth_grant_rules();
CREATE TRIGGER append_only_row BEFORE UPDATE OR DELETE ON access.pairwise_subjects
  FOR EACH ROW EXECUTE FUNCTION access.reject_mutation();

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['oauth_grants', 'oauth_refresh_tokens', 'pairwise_subjects'] LOOP
    EXECUTE format('ALTER TABLE access.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE access.%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('REVOKE ALL ON access.%I FROM PUBLIC', t);
    EXECUTE format('CREATE POLICY rows ON access.%I AS PERMISSIVE USING (true)', t);
    EXECUTE format('CREATE POLICY tenant_scope ON access.%I AS RESTRICTIVE TO access_app '
                   'USING (tenant_id = (SELECT access.tenant_scope()) AND realm_id = (SELECT access.realm_scope())) '
                   'WITH CHECK (tenant_id = (SELECT access.tenant_scope()) AND realm_id = (SELECT access.realm_scope()))', t);
    EXECUTE format('CREATE TRIGGER append_only_truncate BEFORE TRUNCATE ON access.%I '
                   'FOR EACH STATEMENT EXECUTE FUNCTION access.reject_mutation()', t);
  END LOOP;
END
$$;

REVOKE ALL ON FUNCTION access.secure_oauth_partition(regclass) FROM PUBLIC;
REVOKE ALL ON FUNCTION access.oauth_ephemeral_rules() FROM PUBLIC;
REVOKE ALL ON FUNCTION access.oauth_grant_rules() FROM PUBLIC;
REVOKE ALL ON FUNCTION access.open_oauth_day(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION access.open_oauth_day(integer) TO access_archive;
GRANT SELECT, INSERT ON access.oauth_requests, access.oauth_codes, access.client_assertion_replay,
  access.oauth_grants, access.oauth_refresh_tokens, access.pairwise_subjects TO access_app;
GRANT UPDATE (used_ms) ON access.oauth_requests TO access_app;
GRANT UPDATE (redeemed_ms, grant_id) ON access.oauth_codes TO access_app;
GRANT UPDATE (revoked_ms, revoke_reason) ON access.oauth_grants TO access_app;
GRANT UPDATE (rotated_ms) ON access.oauth_refresh_tokens TO access_app;

RESET ROLE;
